 *   - a single string property:   $user->role = 'admin'
 *   - an array of role strings:   $user->roles = ['editor', 'admin']
 *   - an array of role objects:   $user->roles = [(object)['name' => 'admin']]
 *   - a hasRole() method:         $user->hasRole('admin')
 *
