        return (bool) $user->hasRole($adminRole);
    }

    // 2. Single role stored as a string
    if (isset($user->role) && is_string($user->role)) {
        return strcasecmp($user->role, $adminRole) === 0;
    }

    // 3. Multiple roles stored in an array (or iterable)
    if (isset($user->roles) && is_iterable($user->roles)) {
        foreach ($user->roles as $role) {
            // Role as a plain string
            if (is_string($role) && strcasecmp($role, $adminRole) === 0) {
                return true;
            }

            // Role as an object with a "name" property
            if (is_object($role) && isset($role->name) && is_string($role->name)
                && strcasecmp($role->name, $adminRole) === 0) {
                return true;
            }

            // Role as an associative array with a "name" key
            if (is_array($role) && isset($role['name']) && is_string($role['name'])
                && strcasecmp($role['name'], $adminRole) === 0) {
                return true;
            }
        }
    }

    return false;
}
