/**
 * Returns true if any element in the array equals zero.
 *
 * @param int[] $numbers
 * @return bool
 */
function containsZero(array $numbers): bool
{
    foreach ($numbers as $number) {
        if ($number === 0) {
            return true;
        }
    }

    return false;
}
