<?php

/**
 * Determine whether a user object has the admin role.
 *
 * @param  mixed $user  A user object (or null).
 * @return bool
 */
function isAdmin($user): bool
{
    if ($user === null) {
        return false;
    }

    // 1. If the user exposes an isAdmin() method, trust it.
    if (method_exists($user, 'isAdmin')) {
        return (bool) $user->isAdmin();
    }

    // 2. Check a roles collection (e.g. Symfony: array of role strings).
    if (isset($user->roles)) {
        $roles = $user->roles;

        if (is_array($roles)) {
            return in_array('admin', $roles, true);
        }

        if (is_string($roles)) {
            return $roles === 'admin';
        }
    }

    // 3. Fall back to a single role property.
    if (isset($user->role)) {
        return $user->role === 'admin';
    }

    return false;
}
```

**Usage:**

```php
