/**
 * Determine whether the given user has the admin role.
 *
 * Handles the common shapes a "user" can take:
 *  - $user->isAdmin / is_admin / admin   (boolean-ish flag)
 *  - $user->roles / $user->role           (string, array of strings, or role objects)
 *  - $user->hasRole('admin')              (Spatie-style permission helper)
 *
 * @param  mixed $user  User object (or array) for the authenticated user.
 * @return bool
 */
function isAdmin($user): bool
{
    if ($user === null || is_scalar($user)) {
        return false;
    }

    // Read a property from either an array or an object (property or getter).
    $read = is_array($user)
        ? static fn (string $key) => $user[$key] ?? null
        : static function (string $key) use ($user) {
            if (isset($user->{$key})) {
                return $user->{$key};
            }
            $getter = 'get' . ucfirst($key);
            if (method_exists($user, $getter)) {
                return $user->{$getter}();
            }
            return null;
        };

    // 1. Dedicated flag
    foreach (['isAdmin', 'is_admin', 'admin'] as $key) {
        $flag = $read($key);
        if ($flag === null) {
            continue;
        }
        if (is_bool($flag)) {
            if ($flag) {
                return true;
            }
            continue;
        }
        if (in_array($flag, [1, '1', 'true', 'yes'], true)) {
            return true;
        }
    }

    // 2. Framework helper on the model (e.g. Spatie permissions)
    foreach (['hasRole', 'hasAnyRole', 'hasPermission'] as $method) {
        if (method_exists($user, $method)) {
            try {
                if ($user->{$method}('admin') === true) {
                    return true;
                }
            } catch (\Throwable $e) {
                // Helper signature differs — ignore and fall through.
            }
        }
    }

    // 3. Role collection
    foreach (['roles', 'role'] as $key) {
        $roles = $read($key);
        if ($roles === null) {
            continue;
        }
        foreach ((array) $roles as $role) {
            if (is_string($role)) {
                if (strcasecmp(trim($role), 'admin') === 0) {
                    return true;
                }
            } elseif (is_object($role)) {
