{
    return in_array('admin', $user->roles ?? [], true);
}
```

```php
<?php

/**
 * Determines whether the given user has the admin role.
 *
 * Supports objects or arrays, with roles stored as:
 *   - a string:            ['role' => 'admin']
 *   - an array of strings: ['roles' => ['admin', 'editor']]
 *   - an array of objects: ['roles' => [['name' => 'admin'], ...]]
 *
 * @param  object|array|null $user
 * @return bool
 */
function isAdmin($user): bool
{
    if (is_object($user)) {
        $roles  = $user->roles ?? $user->role ?? [];
        $isFlag = $user->is_admin ?? $user->isAdmin ?? false;
    } elseif (is_array($user)) {
        $roles  = $user['roles'] ?? $user['role'] ?? [];
        $isFlag = $user['is_admin'] ?? $user['isAdmin'] ?? false;
    } else {
        return false;
    }

    // Normalize a single role into a list.
    if (is_string($roles)) {
        $roles = [$roles];
    }

    if (!is_array($roles)) {
        $roles = [];
    }

    foreach ($roles as $role) {
        // Role may be an object/array with a `name` property.
        if (is_object($role) && isset($role->name)) {
            $role = $role->name;
        } elseif (is_array($role) && isset($role['name'])) {
            $role = $role['name'];
        }

        if (is_string($role) && strcasecmp($role, 'admin') === 0) {
            return true;
        }
    }

    // Fall back to an explicit boolean flag, if present.
    return (bool) $isFlag;
}
```

**Example usage:**

```php
$user = (object) ['roles' => ['editor', 'admin']];

var_dump(isAdmin($user)); // true
```

**Notes:**
- The function returns `false` for `null`, non-user values, or users with no admin role.
- Role comparison is case-insensitive (`Admin`, `ADMIN`, `admin` all match).
- If your app uses a different shape (e.g., a `permissions` collection or a specific framework's role relation), adjust the normalization logic accordingly.

## Implementation

```php
<?php

declare(strict_types=1);

/**
 * Role names that grant administrator access.
 */
const ADMIN_ROLE_NAMES = ['admin', 'administrator', 'super_admin', 'superadmin'];

/**
 * Extract a flat list of role-name strings from a mixed value.
 *
 * Handles: string, array of strings, array of role objects,
 * a single role object, and objects with __toString().
 *
 * @return list<string>
 */
function extractRoleNames(mixed $value): array
{
    if ($value === null) {
        return [];
    }

    if (is_string($value)) {
        return [$value];
    }

    if (is_array($value)) {
        $names = [];
        foreach ($value as $item) {
            foreach (extractRoleNames($item) as $name) {
                $names[] = $name;
            }
        }
        return $names;
    }

    if (is_object($value)) {
        // A role entity: use its identifying attribute.
        foreach (['name', 'slug', 'role', 'key'] as $attr) {
            if (isset($value->$attr) && is_string($value->$attr)) {
                return [$value->$attr];
            }
        }
        // A value object that can be cast to a string.
        if (method_exists($value, '__toString')) {
            return [(string) $value];
        }
    }

    return [];
}

/**
 * Returns true if the given user has an admin role.
 *
 * @param mixed $user A user object (or array) representing the current user.
 */
function isAdmin(mixed $user): bool
{
    if ($user === null) {
        return false;
    }

    // Normalise the user into an array of readable properties.
    if (is_array($user)) {
        $data = $user;
    } elseif (is_object($user)) {
        $data = get_object_vars($user);
    } else {
        return false;
    }

    // 1. An explicit boolean flag takes precedence.
    foreach (['is_admin', 'isAdmin'] as $flag) {
        if (!empty($data[$flag])) {
            return true;
        }
    }

    // 2. Otherwise inspect the role(s).
    foreach (['roles', 'role', 'user_roles', 'permissions'] as $key) {
        if (!array_key_exists($key, $data)) {
            continue;
        }

        foreach (extractRoleNames($data[$key]) as $roleName) {
            if (in_array(strtolower(trim($roleName)), ADMIN_ROLE_NAMES, true)) {
                return true;
            }
        }
    }

    return false;
}
```

## Usage

```php
// Object with a roles array
$user = new User(['roles' => ['editor', 'admin']]);
var_dump(isAdmin($user));            // bool(true)

// Object with a single role string
$user = new User(['role' => 'Administrator']);
var_dump(isAdmin($user));            // bool(true)

// Eloquent-style model with a roles relation
$user = User::find(1);              // $user->roles = [Role{id:1,name:'admin'}]
var_dump(isAdmin($user));            // bool(true)

// Boolean flag
$user = new User(['is_admin' => true]);
var_dump(isAdmin($user));            // bool(true)

// No admin access
$user = new User(['roles' => ['editor', 'viewer']]);
var_dump(isAdmin($user));            // bool(false)

// Anonymous / missing user
var_dump(isAdmin(null));             // bool(false)
```

## Simpler variant (if you control the schema)

If users always have a `roles` array of strings, you can drop the helpers:

```php
