{
    return in_array('admin', $user->roles ?? [], true);
}
```

## Notes

- **Never trust client input.** Call `isAdmin()` on the *server*, against the user loaded from your session/database — not against a value posted by the browser.
- **Case handling:** role names are compared lowercased, so `Admin`, `ADMIN`, and `admin` all match.
- **Performance:** `get_object_vars()` on a large object is cheap, but if `isAdmin()` is called in a hot loop, cache the result on the user model (e.g. `$user->is_admin`) at load time.
- **Extending:** add new role names to `ADMIN_ROLE_NAMES`, or swap the flag check for a permission-based system (e.g. `can('manage', 'users')`) if your app uses Laravel-style gates.

```php
function isAdmin($user): bool
{
    if ($user === null) {
        return false;
    }

    // Case 1: roles is an array of role names (or an array of role objects).
    if (isset($user->roles) && is_array($user->roles)) {
        foreach ($user->roles as $role) {
            $name = is_object($role) && isset($role->name) ? $role->name : $role;
            if (is_string($name) && strtolower($name) === 'admin') {
                return true;
            }
        }
        return false;
    }

    // Case 2: single role property.
    if (isset($user->role)) {
        $role = is_object($user->role) && isset($user->role->name)
            ? $user->role->name
            : $user->role;

        return is_string($role) && strtolower($role) === 'admin';
    }

    // Case 3: boolean flag.
    if (isset($user->is_admin)) {
        return (bool) $user->is_admin;
    }

    return false;
}
```

Example usage:

```php
$user = (object) ['roles' => ['editor', 'admin']];
var_dump(isAdmin($user)); // bool(true)
```

If your user model uses a different structure (e.g., a `hasRole()` method or a `role_id` lookup), adapt the function accordingly.

```php
/**
 * Determine whether a user object has the admin role.
 *
 * Supports users whose role information is stored as:
 *  - a `roles` array/collection (of strings or objects with a `name`/`slug`)
 *  - a single `role` string
 *  - an `is_admin` boolean flag
 *
 * @param  object|null $user
 * @return bool
 */
function isAdmin($user): bool
{
    if (!is_object($user)) {
        return false;
    }

    // 1) Roles collection: ['admin'], ['user', 'admin'], or Role objects
    if (isset($user->roles)) {
        $roles = $user->roles;

        if (is_array($roles) || $roles instanceof Traversable) {
            foreach ($roles as $role) {
                $name = is_object($role)
                    ? ($role->name ?? $role->slug ?? null)
                    : $role;

                if (is_string($name) && strcasecmp($name, 'admin') === 0) {
                    return true;
                }
            }
        }
    }

    // 2) Single role property: $user->role === 'admin'
    if (isset($user->role) && is_string($user->role)
        && strcasecmp($user->role, 'admin') === 0) {
        return true;
    }

    // 3) Boolean flag: $user->is_admin === true
    if (!empty($user->is_admin)) {
        return true;
    }

    return false;
}
```

**Usage:**

```php
$admin = (object) ['roles' => ['user', 'admin']];
$user  = (object) ['roles' => ['user']];

isAdmin($admin);  // true
isAdmin($user);   // false
isAdmin(null);    // false
```

The function is defensive: it returns `false` for non-objects, handles both array and `Traversable` (e.g. Eloquent `Collection`) role sets, and compares role names case-insensitively. If your app stores roles in a specific format, you can simplify it to just that check.

```php
<?php

/**
 * Checks whether a user object has the admin role.
 *
 * Supports:
 *  - $user->roles as an array (or Traversable) of role names
 *  - $user->role as a single role name
 *  - $user->is_admin as a boolean flag
 *
 * @param  object|array $user
 * @return bool
 */
function isAdmin($user): bool
{
    if (is_array($user)) {
        $user = (object) $user;
    }

    if (!is_object($user)) {
        return false;
    }

    // Explicit admin flag
    if (isset($user->is_admin)) {
        return (bool) $user->is_admin;
    }

    // Roles collection
    if (isset($user->roles)) {
        $roles = is_array($user->roles) || $user->roles instanceof Traversable
            ? $user->roles
            : [$user->roles];

        foreach ($roles as $role) {
            if (is_string($role) && strcasecmp($role, 'admin') === 0) {
                return true;
            }
        }
    }

    // Single role property
    if (isset($user->role) && is_string($user->role)
        && strcasecmp($user->role, 'admin') === 0) {
        return true;
    }

    return false;
}
```

**Example usage:**

```php
